package pagos;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;
public class ValidadorFirmaMercadoPago {private final String secreto;private final Clock clock;private final long toleranciaSegundos;public ValidadorFirmaMercadoPago(String s){this(s,Clock.systemUTC(),300);}public ValidadorFirmaMercadoPago(String s,Clock c,long t){if(s==null||s.isBlank()||c==null||t<=0)throw new IllegalArgumentException("Secreto, reloj y tolerancia son obligatorios.");secreto=s;clock=c;toleranciaSegundos=t;}public boolean validar(String firma,String requestId,String dataId){Map<String,String> p=partes(firma);String ts=p.get("ts"),v1=p.get("v1");if(ts==null||v1==null||requestId==null||requestId.isBlank()||dataId==null||dataId.isBlank())return false;try{long millis=Long.parseLong(ts);long ahora=clock.millis();if(Math.abs(ahora-millis)>toleranciaSegundos*1000L)return false;String manifest="id:"+dataId+";request-id:"+requestId+";ts:"+ts+";";Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secreto.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String esperado=HexFormat.of().formatHex(mac.doFinal(manifest.getBytes(StandardCharsets.UTF_8)));return MessageDigest.isEqual(esperado.getBytes(StandardCharsets.US_ASCII),v1.toLowerCase().getBytes(StandardCharsets.US_ASCII));}catch(Exception e){return false;}}private Map<String,String> partes(String f){Map<String,String> m=new HashMap<>();if(f!=null)for(String x:f.split(",")){String[]p=x.trim().split("=",2);if(p.length==2)m.put(p[0].trim(),p[1].trim());}return m;}}
